import requests,sys,time,uuid
BASE='{{TESTVDB_DB_URL}}'
c='test_mt_tenant'
r=requests.delete(f'{BASE}/v1/schema/{c}')
r=requests.post(f'{BASE}/v1/schema',json={'class':c,'vectorizer':'none','multiTenancyConfig':{'enabled':True},'vectorIndexConfig':{'distance':'cosine','efConstruction':128},'properties':[{'name':'text','dataType':['text']}]})
if r.status_code!=200:print(f'MT setup failed: {r.status_code}');sys.exit(0)
time.sleep(0.5)
r2=requests.post(f'{BASE}/v1/objects',json={'class':c,'id':str(uuid.uuid4()),'vector':[0.1,0.2,0.3,0.4],'properties':{'text':'no_tenant'}})
if r2.status_code==200:print(f'[DEFECT: ILLEGAL_SUCCESS] multi-tenant collection accepted insert without tenant key');sys.exit(1)
else:print(f'multi-tenant insert without tenant properly rejected: status={r2.status_code}');sys.exit(0)

